ECS = [-10, -5, 0, 5, 10]
DCS = [-2, -1, 0, 1, 2]

def uy(x, cs, k):
    if k == 0:
        if x <= cs[0]: return 1.0
        return max(0.0, (cs[1] - x) / (cs[1] - cs[0])) if x < cs[1] else 0.0
    if k == len(cs) - 1:
        if x >= cs[-1]: return 1.0
        return max(0.0, (x - cs[-2]) / (cs[-1] - cs[-2])) if x > cs[-2] else 0.0
    c, a, b = cs[k], cs[k - 1], cs[k + 1]
    if a < x <= c: return (x - a) / (c - a)
    if c < x < b: return (b - x) / (b - c)
    return 0.0

def tsk(e0, d0, K1=4.0, K2=20.0):
    num = den = 0.0
    for i in range(5):
        for j in range(5):
            w = uy(e0, ECS, i) * uy(d0, DCS, j)
            num += w * (K1 * ECS[i] + K2 * DCS[j])
            den += w
    return num / den

