def topla(X, Y):
    return tuple(a + b for a, b in zip(X, Y))

def carp(X, Y):
    return tuple(a * b for a, b in zip(X, Y))

def kesim(T, al):
    return (T[0] + al * (T[1] - T[0]), T[2] - al * (T[2] - T[1]))

def merkez(T):
    return sum(T) / 3

